                    if dd < worst2[0]: worst2 = (dd, n, (round(s,2), [round(v,3) for v in p]))
                    if dd < 0.10 - 0.001: msgs.append("C2: %.4f to %s @%s" % (dd, n, [round(v,3) for v in p]))
