            if dd < sep[0]: sep = (dd, other)
            if dd < 0.15 - 0.001: msgs.append("C5: %.4f from %s" % (dd, other))
        res[rid] = (len(msgs) == 0, msgs, L, bends, worst2, sep)
        if verbose:
